d=$(mktemp -d); F=$d/config.json; printf '{
  "port": 9000,
  greeting: "x"
}
' > $F; node src/app.js $F >$d/out 2>$d/err; echo exit=$?; ! grep -q 'listening on' $d/out && grep -qF "$F" $d/err && echo OK
